 for i,row in enumerate([headers]+rows):
  s+='<w:tr><w:trPr><w:cantSplit/>'+('<w:tblHeader/>' if i==0 else '')+'</w:trPr>'
  for t,v in zip(row,widths):
   s+=f'<w:tc><w:tcPr><w:tcW w:w="{v}" w:type="dxa"/><w:shd w:fill="'+('E8EEF4' if i==0 else 'FFFFFF')+'"/><w:tcMar><w:top w:w="70" w:type="dxa"/><w:bottom w:w="70" w:type="dxa"/><w:left w:w="90" w:type="dxa"/></w:tcMar></w:tcPr><w:p><w:pPr><w:spacing w:after="30"/></w:pPr><w:r><w:rPr><w:sz w:val="19"/>'+('<w:b/>' if i==0 else '')+'</w:rPr><w:t>'+escape(str(t))+'</w:t></w:r></w:p></w:tc>'
  s+='</w:tr>'
 return s+'</w:tbl>'+p()
